WITH gaps AS (SELECT *, CASE WHEN paid_at - LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM payments), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps), metrics AS (SELECT id, paid_at, new_group_flag, island_id, LAG(island_id, 1) OVER (PARTITION BY method ORDER BY island_id, id) AS prev_island_id, AVG(amount) OVER w_grp AS amount_avg_5 FROM sessionized WINDOW w_grp AS (PARTITION BY order_id, status ORDER BY new_group_flag, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW)), metrics_payments AS (SELECT *, PERCENT_RANK() OVER (ORDER BY prev_island_id DESC) AS prev_island_id_percent_rank, SUM(amount_avg_5) OVER (ORDER BY island_id, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount_avg_5 FROM metrics WHERE HOUR(paid_at) BETWEEN 10 AND 16), metrics_payments_2 AS (SELECT id, paid_at, new_group_flag, island_id, amount_avg_5, prev_island_id_percent_rank, cumulative_amount_avg_5, LAG(prev_island_id) OVER w_grp AS prev_prev_island_id, LEAD(island_id) OVER w_grp AS next_island_id, ROW_NUMBER() OVER w_grp AS row_seq, LAST_VALUE(prev_island_id_percent_rank, TRUE) OVER (ORDER BY prev_island_id, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_prev_island_id_percent_rank FROM metrics_payments WINDOW w_grp AS (ORDER BY new_group_flag, id)), enriched AS (SELECT *, SUM(row_seq) OVER (ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_row_seq, SUM(prev_island_id_percent_rank) OVER w_hist AS prev_island_id_percent_rank_sum_90d, LAST_VALUE(amount_avg_5, TRUE) OVER (ORDER BY new_group_flag, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount_avg_5, LEAD(island_id, 2) OVER w_recent AS next_island_id_2 FROM metrics_payments_2 WINDOW w_hist AS (ORDER BY CAST(paid_at AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW), w_recent AS (ORDER BY amount_avg_5, id)) SELECT id, paid_at, new_group_flag, prev_island_id_percent_rank, cumulative_amount_avg_5, prev_prev_island_id, next_island_id, row_seq, cumulative_row_seq FROM enriched ORDER BY prev_prev_island_id DESC NULLS FIRST, prev_island_id_percent_rank
